function render(){const total=state.tasks.filter(x=>x.done).reduce((a,x)=>a+x.points,0);
$('#app').innerHTML=`<div class="stats">${stat('本周已赚 / 分',total)}${stat('完成任务',state.tasks.filter(x=>x.done).length)}${stat('已结算周数',state.weeks.length)}</div><div class="grid"><div>${panel('让家务成为一份合作',state.tasks.map(x=>`<div class="item"><div><strong>${esc(x.name)}</strong><p>${x.points} 积分 · ${x.done?'已完成':'等待行动'}</p></div><div class="row"><button data-action="${x.id}" class="${x.done?'selected':''}">${x.done?'撤销完成':'完成'}</button><button data-delete="${x.id}" class="small" aria-label="删除${esc(x.name)}">删除</button></div></div>`).join('')||empty())}${panel('设计新任务',`<form id="task" class="stack"><div class="fields">${field('任务名称','name','text','','required maxlength="40"')}${field('完成积分','points','number',5,'required min="1" max="100"')}</div><button class="primary">添加任务</button></form>`)}</div><div>${panel('本周结算窗口',`<h2>${total} 积分</h2><p>完成状态可以撤销；确认结算后，将本周积分归档并开始新一周。</p><button id="settle" class="primary" ${total?'':'disabled'}>结算本周，开始下一周</button>`,'tint')}${panel('积分存折',state.weeks.slice().reverse().map((x,i)=>`<div class="item"><div>第 ${state.weeks.length-i} 周<p>${x.date} · ${x.count} 项任务</p></div><b>+${x.points}</b></div>`).join('')||empty('完成几件家务后，来做第一次周结算。'))}</div></div>`;
form('task',v=>{state.tasks.push({id:uid(),name:v.name,points:+v.points,done:false});commit()});actions('[data-action]',id=>{const x=state.tasks.find(x=>x.id===id);x.done=!x.done;commit()});$$('[data-delete]').forEach(b=>b.onclick=()=>{state.tasks=state.tasks.filter(x=>x.id!==b.dataset.delete);commit()});on('settle',()=>{state.weeks.push({date:today(),points:total,count:state.tasks.filter(x=>x.done).length});state.tasks.forEach(x=>x.done=false);commit();toast('本周已归档，任务已准备好迎接新一周')})}render();
